`timescale 1ns/1ps

module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg clk;
    reg areset;
    reg x;
    wire z;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .areset(areset),
        .x(x),
        .z(z)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;

    // Task to apply reset
    task apply_reset;
        begin
            areset = 1'b1;
            x = 1'b0;
            #12;
            areset = 1'b0;
            #3;
        end
    endtask

    // Test vector checking task
    task check_bit(input reg expected_z);
        begin
            @(posedge clk);
            #1; // small delay to allow combinatorial propagation after clock edge
            if (z !== expected_z) begin
                $display("Time %0t: Mismatch! x=%b, z=%b, expected_z=%b", $time, x, z, expected_z);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        areset = 0;
        x = 0;

        // Test 1: Reset behavior
        apply_reset();
        // After reset, state is S0, z should mirror x immediately or on next clk depending on architecture.
        // Let's test streaming bits for 2's complement of 6 (binary ...00110, LSB first: 0, 1, 1, 0, 0)
        // 6 in binary: 00110. LSB to MSB: 0, 1, 1, 0, 0...
        // 2's complement of 6 is -6: binary 11010. LSB to MSB: 0, 1, 0, 1, 1...

        // Let's test number 6 (0, 1, 1, 0, 0) -> expected output (-6): (0, 1, 0, 1, 1)
        // Note: The DUT uses Moore state machine where z is combinationally dependent on state and x.

        apply_reset();

        // Stream LSB of 6: x = 0 (S0 -> S0, z = 0)
        x = 1'b0;
        check_bit(1'b0);

        // Stream next bit of 6: x = 1 (S0 -> S1, z = 1)
        x = 1'b1;
        check_bit(1'b1);

        // Stream next bit of 6: x = 1 (S1 -> S1, z = ~1 = 0)
        x = 1'b1;
        check_bit(1'b0);

        // Stream next bit of 6: x = 0 (S1 -> S1, z = ~0 = 1)
        x = 1'b0;
        check_bit(1'b1);

        // Stream next bit of 6: x = 0 (S1 -> S1, z = ~0 = 1)
        x = 1'b0;
        check_bit(1'b1);

        // Test 2: Asynchronous reset mid-stream
        areset = 1'b1;
        #7;
        areset = 1'b0;
        #3;

        // Test number 3 (binary 00011, LSB first: 1, 1, 0, 0, 0)
        // 2's complement of 3 is -3: binary 11101, LSB first: 1, 0, 1, 1, 1

        // LSB: x = 1 (S0 -> S1, z = 1)
        x = 1'b1;
        check_bit(1'b1);

        // Next: x = 1 (S1 -> S1, z = 0)
        x = 1'b1;
        check_bit(1'b0);

        // Next: x = 0 (S1 -> S1, z = 1)
        x = 1'b0;
        check_bit(1'b1);

        // Next: x = 0 (S1 -> S1, z = 1)
        x = 1'b0;
        check_bit(1'b1);

        // Next: x = 0 (S1 -> S1, z = 1)
        x = 1'b0;
        check_bit(1'b1);

        #20;

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
